WITH recent_subscriptions AS (SELECT *, UPPER(status) AS status_upper FROM subscriptions WHERE status IN ('CANCELLED', 'PAUSED', 'ACTIVE')), PlanSummary AS (SELECT plan, CASE WHEN monthly_fee >= 199 THEN 'high' WHEN monthly_fee >= 101 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(*) AS row_count FROM recent_subscriptions GROUP BY plan, CASE WHEN monthly_fee >= 199 THEN 'high' WHEN monthly_fee >= 101 THEN 'mid' ELSE 'low' END) SELECT * FROM PlanSummary ORDER BY row_count DESC;
